#!/usr/bin/env python3
"""Quality Evaluator: compares an output against your criteria (Anthropic API).

Usage:
  python evaluador.py --salida respuesta.txt --criterios criterios.txt
  python evaluador.py --salida respuesta.txt --criterios criterios.txt --contexto pregunta.txt

Requirements:
  pip install anthropic
  export ANTHROPIC_API_KEY="your-key"

criterios.txt format: one criterion per line. Lines starting with
"!" are disqualifying (a score below 5 there = automatic fail). Example:
  ! Does not invent data that isn't in the context
  ! Treats the customer respectfully at all times
  Answers everything that's asked
  Warm, professional tone
  Under 150 words
"""

import argparse
import json
import os
import sys
from pathlib import Path

try:
    import anthropic
except ImportError:
    sys.exit("Missing the Anthropic SDK. Install it with: pip install anthropic")

# ── Configuration ───────────────────────────────────────────────────────

MODELO = "claude-sonnet-5"  # judging well requires a strong model
NOTA_APTO = 7.0      # minimum weighted average to pass
NOTA_REVISAR = 5.0   # between this and NOTA_APTO stays in 'needs review'
MAX_CARACTERES = 40000

SISTEMA = (
    "You are a demanding, fair quality evaluator. "
    "I'll give you an OUTPUT to evaluate, a list of CRITERIA and, sometimes, the "
    "CONTEXT that originated it. Evaluate each criterion separately by calling "
    "the tool. Rules: score from 0 (total non-compliance) to 10 "
    "(flawless compliance); the evidence for each criterion cites literal "
    "text from the output (or points out what's missing); do not reward length or "
    "a confident tone: evaluate only what the criterion asks; if a "
    "criterion doesn't apply to this output, score 10 and say so in the evidence. "
    "Be the evaluator you'd want to have: tough on failures, concrete "
    "about how to fix them."
)

HERRAMIENTA = {
    "name": "registrar_evaluacion",
    "description": "Records the criterion-by-criterion evaluation of the output.",
    "strict": True,
    "input_schema": {
        "type": "object",
        "properties": {
            "criterios": {
                "type": "array",
                "description": "One item per criterion, in the same order received.",
                "items": {
                    "type": "object",
                    "properties": {
                        "criterio": {"type": "string", "description": "The criterion evaluated, verbatim."},
                        "nota": {"type": "number", "minimum": 0, "maximum": 10},
                        "evidencia": {
                            "type": "string",
                            "description": "Concrete quote or gap that justifies the score.",
                        },
                        "mejora": {
                            "type": ["string", "null"],
                            "description": "What to change to raise the score; null if already 10.",
                        },
                    },
                    "required": ["criterio", "nota", "evidencia", "mejora"],
                    "additionalProperties": False,
                },
            },
            "resumen": {
                "type": "string",
                "description": "Overall assessment in 2-3 sentences.",
            },
        },
        "required": ["criterios", "resumen"],
        "additionalProperties": False,
    },
}

# ── Logic ──────────────────────────────────────────────────────────────


def leer(ruta: str, obligatorio: bool = True) -> str:
    if not ruta:
        return ""
    try:
        texto = Path(ruta).read_text(encoding="utf-8", errors="replace").strip()
    except OSError as e:
        sys.exit(f"Can't read {ruta}: {e}")
    if obligatorio and not texto:
        sys.exit(f"File {ruta} is empty.")
    return texto


def cargar_criterios(ruta: str) -> list[dict]:
    """Returns [{texto, eliminatorio}] from the criteria file."""
    criterios = []
    for linea in leer(ruta).splitlines():
        linea = linea.strip()
        if not linea or linea.startswith("#"):
            continue
        eliminatorio = linea.startswith("!")
        criterios.append({"texto": linea.lstrip("! ").strip(), "eliminatorio": eliminatorio})
    if not criterios:
        sys.exit("The criteria file has no criteria.")
    return criterios


def evaluar(client: "anthropic.Anthropic", salida: str, criterios: list[dict], contexto: str) -> dict:
    lista = "\n".join(f"{i + 1}. {c['texto']}" for i, c in enumerate(criterios))
    partes = []
    if contexto:
        partes.append(f"CONTEXT (what originated the output):\n{contexto}")
    partes.append(f"CRITERIA:\n{lista}")
    partes.append(f"OUTPUT TO EVALUATE:\n{salida}")
    respuesta = client.messages.create(
        model=MODELO,
        max_tokens=3000,
        system=SISTEMA,
        tools=[HERRAMIENTA],
        tool_choice={"type": "tool", "name": "registrar_evaluacion"},
        messages=[{"role": "user", "content": "\n\n".join(partes)}],
    )
    for bloque in respuesta.content:
        if bloque.type == "tool_use" and bloque.name == "registrar_evaluacion":
            return dict(bloque.input)
    raise RuntimeError("The API did not return the expected evaluation.")


def veredicto_final(evaluacion: dict, criterios: list[dict]) -> dict:
    """The verdict is computed by the code with fixed rules, not by the model."""
    notas = evaluacion.get("criterios", [])
    if len(notas) != len(criterios):
        print(
            f"WARNING: expected {len(criterios)} criteria but got {len(notas)}; "
            "the verdict is computed with the ones received.",
            file=sys.stderr,
        )
    eliminatorio_suspendido = False
    suma = 0.0
    for i, item in enumerate(notas):
        nota = float(item.get("nota", 0))
        suma += nota
        es_eliminatorio = i < len(criterios) and criterios[i]["eliminatorio"]
        item["eliminatorio"] = es_eliminatorio
        if es_eliminatorio and nota < 5:
            eliminatorio_suspendido = True
    media = round(suma / len(notas), 2) if notas else 0.0

    if eliminatorio_suspendido:
        veredicto = "no_apto"
    elif media >= NOTA_APTO:
        veredicto = "apto"
    elif media >= NOTA_REVISAR:
        veredicto = "revisar"
    else:
        veredicto = "no_apto"

    return {
        "veredicto": veredicto,
        "nota_media": media,
        "eliminatorio_suspendido": eliminatorio_suspendido,
        "criterios": notas,
        "resumen": evaluacion.get("resumen", ""),
    }


def main() -> None:
    parser = argparse.ArgumentParser(description="Evaluates an output against your criteria.")
    parser.add_argument("--salida", required=True, help="File with the text to evaluate")
    parser.add_argument("--criterios", required=True, help="File with one criterion per line ('!' = disqualifying)")
    parser.add_argument("--contexto", help="Optional file with the original question/request")
    args = parser.parse_args()

    if not os.environ.get("ANTHROPIC_API_KEY"):
        sys.exit(
            "Missing the ANTHROPIC_API_KEY environment variable.\n"
            "Create the key at console.anthropic.com and export it before running."
        )

    salida = leer(args.salida)
    contexto = leer(args.contexto, obligatorio=False) if args.contexto else ""
    criterios = cargar_criterios(args.criterios)
    if len(salida) > MAX_CARACTERES:
        print(f"WARNING: output truncated to {MAX_CARACTERES} characters.", file=sys.stderr)
        salida = salida[:MAX_CARACTERES]

    client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY from the environment

    try:
        evaluacion = evaluar(client, salida, criterios, contexto)
    except anthropic.AuthenticationError:
        sys.exit("Invalid or revoked API key. Check ANTHROPIC_API_KEY.")
    except anthropic.RateLimitError:
        sys.exit("Rate limit reached. Wait a minute and retry.")
    except anthropic.APIStatusError as e:
        sys.exit(f"API error ({e.status_code}): {e.message}")
    except anthropic.APIConnectionError:
        sys.exit("No connection to the API. Check your network and retry.")

    resultado = veredicto_final(evaluacion, criterios)
    print(json.dumps(resultado, ensure_ascii=False, indent=2))

    # Exit code useful for chaining: 0 pass, 2 needs review, 3 fail.
    sys.exit({"apto": 0, "revisar": 2, "no_apto": 3}[resultado["veredicto"]])


if __name__ == "__main__":
    main()
